-- Tracker's database. Entity ids are generated by clients (UUIDs, as text).
-- sync_action is the sync log: one row per change, written by tracker-api in
-- the same transaction as the change, numbered from sync_id_seq.

CREATE SEQUENCE sync_id_seq;

CREATE TABLE workspace (
    id   int PRIMARY KEY,
    name text NOT NULL
);

CREATE TABLE app_user (
    id           text PRIMARY KEY,
    workspace_id int  NOT NULL REFERENCES workspace (id),
    name         text NOT NULL,
    email        text NOT NULL
);

CREATE TABLE team (
    id           text PRIMARY KEY,
    workspace_id int  NOT NULL REFERENCES workspace (id),
    key          text NOT NULL,
    name         text NOT NULL,
    next_number  int  NOT NULL DEFAULT 1
);

CREATE TABLE issue (
    id           text PRIMARY KEY,
    workspace_id int         NOT NULL REFERENCES workspace (id),
    team_id      text        NOT NULL REFERENCES team (id),
    number       int         NOT NULL,
    title        text        NOT NULL,
    description  text        NOT NULL DEFAULT '',
    state        text        NOT NULL DEFAULT 'todo',
    priority     int         NOT NULL DEFAULT 0,
    assignee_id  text        REFERENCES app_user (id),
    creator_id   text        NOT NULL REFERENCES app_user (id),
    created_at   timestamptz NOT NULL,
    updated_at   timestamptz NOT NULL,
    sync_id      bigint      NOT NULL,
    UNIQUE (team_id, number)
);

CREATE TABLE comment (
    id           text PRIMARY KEY,
    workspace_id int         NOT NULL REFERENCES workspace (id),
    issue_id     text        NOT NULL REFERENCES issue (id) ON DELETE CASCADE,
    user_id      text        NOT NULL REFERENCES app_user (id),
    body         text        NOT NULL,
    created_at   timestamptz NOT NULL,
    updated_at   timestamptz NOT NULL,
    sync_id      bigint      NOT NULL
);
CREATE INDEX comment_issue ON comment (issue_id);

CREATE TABLE sync_action (
    id           bigint PRIMARY KEY,
    workspace_id int         NOT NULL,
    model        text        NOT NULL,   -- issue | comment
    model_id     text        NOT NULL,
    action       text        NOT NULL,   -- I insert | U update | D delete
    data         jsonb       NOT NULL,   -- the entity after the change
    delta        jsonb,                  -- the fields an update changed
    actor_id     text,                   -- the user who made the change
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX sync_action_workspace ON sync_action (workspace_id, id);
CREATE INDEX sync_action_model ON sync_action (model_id, id);

-- A workspace's recovery page: lost changes that could not be put back.
CREATE TABLE recovery_item (
    workspace_id int         NOT NULL REFERENCES workspace (id),
    action_id    bigint      NOT NULL,
    note         text        NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, action_id)
);
